/**
 * 生成径向渐变字符串
 */
export function radialGradient(colorArr) {
  return 'radial-gradient(circle, ' + colorArr.join(', ') + ')'
}

/**
 * 赛博朋克风格：霓虹发光边框
 */
export function neonBorder(color, width) {
  width = width || 1
  return width + 'px solid ' + color
}

/**
 * 赛博朋克风格：霓虹光效阴影
 */
export function neonGlow(color, intensity) {
  intensity = intensity || 1
  var size = Math.round(20 * intensity)
  return '0 0 ' + size + 'px ' + color + ', 0 0 ' + (size * 2) + 'px ' + color + '40'
}

/**
 * 赛博朋克风格：扫描线效果
 */
export function scanlineEffect(opacity) {
  opacity = opacity || 0.03
  return 'repeating-linear-gradient(0deg, rgba(0, 255, 229, ' + opacity + ') 0px, rgba(0, 255, 229, ' + opacity + ') 1px, transparent 1px, transparent 2px)'
}

/**
 * 赛博朋克风格：全息投影效果
 */
export function hologramEffect() {
  return 'linear-gradient(135deg, rgba(0, 255, 229, 0.1) 0%, rgba(139, 92, 246, 0.1) 50%, rgba(255, 0, 255, 0.1) 100%)'
}

/**
 * 赛博朋克风格：故障艺术闪烁
 */
export function glitchFlicker() {
  return 'animation: glitch 0.3s infinite'
}

