drawDataFlow() {
  var page = this
  var size = getScreenShape().screenWidth
  if (!size) { return }
  try {
    var canvas = page.$element("dataFlowCanvas")
    if (!canvas) { return }
    var ctx = canvas.getContext("2d")
    if (!ctx) { return }
    var T = getThemeColors()

    var width = size
    var height = size

    ctx.clearRect(0, 0, width, height)

    // 绘制数据流动效果（垂直扫描线）
    var time = Date.now() / 1000
    var lineCount = 8
    var spacing = width / lineCount

    for (var i = 0; i < lineCount; i++) {
      var x = i * spacing + (time * 20) % spacing
      var alpha = 0.1 + 0.1 * Math.sin(time * 2 + i * 0.5)

      ctx.beginPath()
      ctx.strokeStyle = T.neonCyan + Math.round(alpha * 255).toString(16).padStart(2, '0')
      ctx.lineWidth = 1
      ctx.moveTo(x, 0)
      ctx.lineTo(x, height)
      ctx.stroke()
    }

    // 绘制水平数据流
    var hLineCount = 6
    var hSpacing = height / hLineCount

    for (var j = 0; j < hLineCount; j++) {
      var y = j * hSpacing + (time * 15) % hSpacing
      var alphaH = 0.05 + 0.05 * Math.sin(time * 1.5 + j * 0.7)

      ctx.beginPath()
      ctx.strokeStyle = T.neonPurple + Math.round(alphaH * 255).toString(16).padStart(2, '0')
      ctx.lineWidth = 0.5
      ctx.moveTo(0, y)
      ctx.lineTo(width, y)
      ctx.stroke()
    }
  } catch (e) { /* skip */ }
},

