_renderTicks(size) {
  try {
    var canvas = this.$element("tickCanvas")
    if (!canvas) { return }
    var ctx = canvas.getContext("2d")
    if (!ctx) { return }
    var T = getThemeColors()
    var cx = size / 2
    var cy = size / 2
    ctx.clearRect(0, 0, size, size)

    // 外圈渐变环
    ctx.beginPath()
    ctx.lineWidth = 1.5
    ctx.strokeStyle = T.primary + '25'
    ctx.arc(cx, cy, size / 2 - 6, 0, Math.PI * 2)
    ctx.stroke()

    // 60 刻度
    for (var i = 0; i < 60; i++) {
      var ang = (i / 60) * Math.PI * 2 - Math.PI / 2
      var isMajor = (i % 5 === 0)
      var r1 = size / 2 - 9
      var r2 = size / 2 - (isMajor ? 18 : 14)
      ctx.beginPath()
      ctx.lineWidth = isMajor ? 2.5 : 1
      ctx.strokeStyle = isMajor ? T.primary + '80' : T.primary + '30'
      ctx.moveTo(cx + r1 * Math.cos(ang), cy + r1 * Math.sin(ang))
      ctx.lineTo(cx + r2 * Math.cos(ang), cy + r2 * Math.sin(ang))
      ctx.stroke()
    }

    // 秒针 — 带光晕拖尾
    var now = new Date()
    var sec = now.getSeconds()
    var secAng = (sec / 60) * Math.PI * 2 - Math.PI / 2
    var secR1 = size / 2 - 22
    var secR2 = size / 2 - 38
    drawGlowHand(ctx, cx, cy, secR1, secR2, secAng, T.primary)
  } catch (e) { /* canvas 不可用时降级 */ }
},

