drawPulseWave() {
  var page = this
  var size = getScreenShape().screenWidth
  if (!size) { return }
  try {
    var canvas = page.$element("pulseCanvas")
    if (!canvas) { return }
    var ctx = canvas.getContext("2d")
    if (!ctx) { return }
    var T = getThemeColors()

    var width = size
    var height = 60
    var cy = height / 2
    var opacity = parseFloat(page.hintOpacity) || 0.5

    ctx.clearRect(0, 0, width, height)

    // 绘制脉搏波形
    ctx.beginPath()
    ctx.strokeStyle = T.accent + Math.round(opacity * 60).toString(16).padStart(2, '0')
    ctx.lineWidth = 2
    ctx.lineCap = "round"
    ctx.lineJoin = "round"

    var time = Date.now() / 1000
    var frequency = 1.2

    for (var x = 0; x < width; x++) {
      var t = (x / width) * Math.PI * 4 + time * frequency
      var y = cy
      var phase = t % (Math.PI * 2)
      if (phase > 2.5 && phase < 3.0) {
        y = cy - Math.sin((phase - 2.5) * Math.PI * 4) * 20
      } else if (phase > 3.0 && phase < 3.3) {
        y = cy - Math.sin((phase - 3.0) * Math.PI * 3.33) * 8
      } else {
        y = cy + Math.sin(t * 0.5) * 2
      }
      if (x === 0) { ctx.moveTo(x, y) } else { ctx.lineTo(x, y) }
    }
    ctx.stroke()
  } catch (e) { /* skip */ }
},

