input.old_string:
drawDialRing() {
  if (!this.dialW) { return }
  var page = this
  var size = this.dialW
  var T = getThemeColors()
  var pct = Math.min(Math.max(this.stepProgress / 100, 0), 1)
  setTimeout(function() {
    try {
      var canvas = page.$element("dialCanvas")
      if (!canvas) { return }
      var ctx = canvas.getContext("2d")
      if (!ctx) { return }
      var lineWidth = Math.max(7, Math.round(size * 0.055))
      var cx = size / 2
      var cy = size / 2
      var r = size / 2 - lineWidth / 2 - 3
      ctx.clearRect(0, 0, size, size)

      // 渐变进度环
      drawGradientArc(ctx, cx, cy, r, lineWidth, pct, T.gradientSteps, {
        trackColor: T.primary + '18',
        glowSize: 8,
        glow: pct > 0.01
      })

      // 内圈细导环
      ctx.beginPath()
      ctx.lineWidth = 1.5
      ctx.strokeStyle = T.primary + '10'
      ctx.arc(cx, cy, r - lineWidth / 2 - 4, 0, Math.PI * 2)
      ctx.stroke()
    } catch (e) { /* canvas 不可用时降级 */ }
  }, 30)
},

