drawDialRing() {
  if (!this.dialW) { return }
  var page = this
  var size = this.dialW
  var T = getThemeColors()
  var pct = Math.min(Math.max(this.stepProgress / 100, 0), 1)
  setTimeout(function() {
    try {
      var canvas = page.$element("dialCanvas")
      if (!canvas) { return }
      var ctx = canvas.getContext("2d")
      if (!ctx) { return }
      var lineWidth = Math.max(7, Math.round(size * 0.055))
      var cx = size / 2
      var cy = size / 2
      var r = size / 2 - lineWidth / 2 - 3
      ctx.clearRect(0, 0, size, size)

      // 霓虹渐变进度环
      drawGradientArc(ctx, cx, cy, r, lineWidth, pct, T.gradientSteps, {
        trackColor: T.neonCyan + '18',
        glowSize: 10,
        glow: pct > 0.01,
        glowColor: T.neonCyan
      })

      // 内圈细导环（霓虹发光）
      ctx.beginPath()
      ctx.lineWidth = 1.5
      ctx.strokeStyle = T.neonCyan + '20'
      ctx.shadowColor = T.neonCyan
      ctx.shadowBlur = 5
      ctx.arc(cx, cy, r - lineWidth / 2 - 4, 0, Math.PI * 2)
      ctx.stroke()
      ctx.shadowBlur = 0
    } catch (e) { /* canvas 不可用时降级 */ }
  }, 30)
},

