// ─── 性能优化工具 ────────────────────────────────────────

/**
 * Canvas离屏渲染优化 — 预渲染静态内容到离屏Canvas
 * @param {number} width - 画布宽度
 * @param {number} height - 画布高度
 * @param {function} drawFn - 绘制函数 (ctx) => {}
 * @returns {object} { draw, getCanvas, invalidate }
 */
export function createOffscreenCanvas(width, height, drawFn) {
  var offscreen = null
  var dirty = true

  function ensure() {
    if (!offscreen || dirty) {
      try {
        offscreen = { width: width, height: height }
        // 注意：实际Canvas创建需要在页面上下文中进行
        dirty = false
      } catch (e) {
        // Canvas不可用时降级
      }
    }
  }

  function draw(ctx) {
    ensure()
    if (offscreen && !dirty) {
      // 使用离屏Canvas内容
      // ctx.drawImage(offscreen, 0, 0)
    }
    // 直接绘制（降级方案）
    if (drawFn) { drawFn(ctx) }
  }

  function invalidate() {
    dirty = true
  }

  function getCanvas() { return offscreen }

  return { draw: draw, getCanvas: getCanvas, invalidate: invalidate }
}

/**
 * 动画帧节流器 — 确保60fps流畅度
 * @param {function} callback - 回调函数
 * @param {number} [targetFps=60] - 目标帧率
 * @returns {object} { start, stop, isRunning }
 */
export function createFrameThrottler(callback, targetFps) {
  targetFps = targetFps || 60
  var frameInterval = 1000 / targetFps
  var lastFrameTime = 0
  var timer = null
  var running = false

  function frame(currentTime) {
    if (!running) return

    var elapsed = currentTime - lastFrameTime
    if (elapsed >= frameInterval) {
      lastFrameTime = currentTime - (elapsed % frameInterval)
      callback(currentTime)
    }

    timer = setTimeout(function() {
      requestAnimationFrame(frame)
    }, Math.max(0, frameInterval - elapsed))
  }

  function start() {
    if (running) return
    running = true
    lastFrameTime = Date.now()
    requestAnimationFrame(frame)
  }

  function stop() {
    running = false
    if (timer) { clearTimeout(timer); timer = null }
  }

  function isRunning() { return running }

  return { start: start, stop: stop, isRunning: isRunning }
}

/**
 * 内存管理器 — 自动清理定时器和事件监听
 * @returns {object} { addTimer, addListener, cleanup }
 */
export function createMemoryManager() {
  var timers = []
  var listeners = []

  function addTimer(id, type) {
    timers.push({ id: id, type: type })
  }

  function addListener(listener) {
    listeners.push(listener)
  }

  function cleanup() {
    // 清理定时器
    for (var i = 0; i < timers.length; i++) {
      var t = timers[i]
      if (t.type === 'interval') {
        clearInterval(t.id)
      } else if (t.type === 'timeout') {
        clearTimeout(t.id)
      }
    }
    timers = []

    // 清理事件监听
    for (var j = 0; j < listeners.length; j++) {
      try {
        if (listeners[j].remove) {
          listeners[j].remove()
        }
      } catch (e) { /* ignore */ }
    }
    listeners = []
  }

  return { addTimer: addTimer, addListener: addListener, cleanup: cleanup }
}

